@startuml

class Student {
  + StudentID : int
  + BirthDate : date
  + BirthCity : string
  + BirthRegion : string
  + EnrollmentYear : int
}

class Professor {
  + Name : string
  + BirthDate : date
  + BirthCity : string
}

class Faculty {
  + Name : string
  + Type : string
}

class Course {
  + Code : string
  + LectureHours : int
}

class Exam {
  + Grade : float
}

Faculty "1" -- "*" Student : enrolls
Faculty "1" -- "*" Course : belongs to
Professor "1" -- "*" Course : teaches
Student "1" -- "*" Exam : passes
Course "1" -- "*" Exam : is subject of

@enduml

